using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEngine.Rendering.RenderGraphModule;using UnityEngine.Experimental.Rendering;
public static class Socket216Layers{
 public static Socket216View Current;public static readonly string[]Names={"BackingOwn","BaseWithBacking","RegisteredHair284","OtherHair","TaggedWholeHair"};
 public sealed class Set:IDisposable{public RTHandle rgba,meta,uv,world,depth;public Set(string n){rgba=RTHandles.Alloc(960,544,colorFormat:GraphicsFormat.R8G8B8A8_SRGB,filterMode:FilterMode.Point,name:n+"RGBA");meta=RTHandles.Alloc(960,544,colorFormat:GraphicsFormat.R32G32B32A32_SFloat,filterMode:FilterMode.Point,name:n+"META");uv=RTHandles.Alloc(960,544,colorFormat:GraphicsFormat.R32G32B32A32_SFloat,filterMode:FilterMode.Point,name:n+"UV");world=RTHandles.Alloc(960,544,colorFormat:GraphicsFormat.R32G32B32A32_SFloat,filterMode:FilterMode.Point,name:n+"WORLD");depth=RTHandles.Alloc(960,544,depthBufferBits:DepthBits.Depth32,filterMode:FilterMode.Point,name:n+"DEPTH");}public void Dispose(){rgba.Release();meta.Release();uv.Release();world.Release();depth.Release();}}
 public static Set[]Sets;public static void Ensure(){if(Sets==null)Sets=Names.Select(n=>new Set("H216"+n)).ToArray();}public static void Dispose(){if(Sets!=null)foreach(var x in Sets)x.Dispose();Sets=null;Current=null;}
}
public sealed class Socket216Feature:ScriptableRendererFeature{
 Pass pass;public override void Create(){pass=new Pass{renderPassEvent=RenderPassEvent.AfterRenderingTransparents};}public override void AddRenderPasses(ScriptableRenderer r,ref RenderingData d){var v=Socket216Layers.Current;if(v&&Eye202Layers.Enabled&&d.cameraData.camera==v.pose.source.Layers.game.actor.inheritedView.worldCamera)r.EnqueuePass(pass);}
 sealed class Data{public Renderer[]rr;public Material[]mm;public int[]ss;public float[]tags;public int part;public bool backing;public Mesh mesh;public Matrix4x4 matrix;public Material skin;}
 sealed class Pass:ScriptableRenderPass{public override void RecordRenderGraph(RenderGraph g,ContextContainer frame){Socket216Layers.Ensure();var v=Socket216Layers.Current;for(int p=0;p<5;p++){using var b=g.AddRasterRenderPass<Data>("H216 "+Socket216Layers.Names[p],out var d);var t=Socket216Layers.Sets[p];b.SetRenderAttachment(g.ImportTexture(t.rgba),0,AccessFlags.Write);b.SetRenderAttachment(g.ImportTexture(t.meta),1,AccessFlags.Write);b.SetRenderAttachment(g.ImportTexture(t.uv),2,AccessFlags.Write);b.SetRenderAttachment(g.ImportTexture(t.world),3,AccessFlags.Write);b.SetRenderAttachmentDepth(g.ImportTexture(t.depth),AccessFlags.Write);b.UseAllGlobalTextures(true);var res=frame.Get<UniversalResourceData>();if(res.mainShadowsTexture.IsValid())b.UseTexture(res.mainShadowsTexture,AccessFlags.Read);if(res.additionalShadowsTexture.IsValid())b.UseTexture(res.additionalShadowsTexture,AccessFlags.Read);b.AllowPassCulling(false);b.AllowGlobalStateModification(true);var rr=new List<Renderer>();var mm=new List<Material>();var ss=new List<int>();var tags=new List<float>();
   if(p==1){foreach(var r in v.pose.source.Layers.game.sourceRenderers){for(int k=0;k<r.sharedMaterials.Length;k++){var m=r.sharedMaterials[k];int role=Mathf.RoundToInt(m.GetFloat("_E151Role"));if(!Eye202Layers.Selected(8,role))continue;rr.Add(r);mm.Add(m);ss.Add(k);tags.Add(0);}}}if(p==2||p==4){rr.Add(v.registered);mm.Add(v.registered.sharedMaterial);ss.Add(0);tags.Add(1);}if(p==3||p==4){for(int k=0;k<4;k++){rr.Add(v.other);mm.Add(v.other.sharedMaterials[k]);ss.Add(k);tags.Add(0);}}
   d.rr=rr.ToArray();d.mm=mm.ToArray();d.ss=ss.ToArray();d.tags=tags.ToArray();d.part=p<2?(p==0?0:8):6;d.backing=p<2;d.mesh=v.backing.sharedMesh;d.matrix=v.backing.transform.localToWorldMatrix;d.skin=v.faceSkin; b.SetRenderFunc(static(Data d,RasterGraphContext c)=>{c.cmd.ClearRenderTarget(RTClearFlags.All,Color.clear,1,0);c.cmd.SetGlobalFloat("_E202Part",d.part);for(int k=0;k<d.rr.Length;k++){c.cmd.SetGlobalFloat("_H216SourceTag",d.tags[k]);c.cmd.DrawRenderer(d.rr[k],d.mm[k],d.ss[k],d.mm[k].FindPass("IndependentEye202"));}if(d.backing){c.cmd.SetGlobalFloat("_H216SourceTag",0);c.cmd.DrawMesh(d.mesh,d.matrix,d.skin,0,d.skin.FindPass("IndependentEye202"));}c.cmd.SetGlobalFloat("_E202Part",-1);c.cmd.SetGlobalFloat("_H216SourceTag",0);});
  }}}
}
